import "strings"

// StripAPIPrefix removes the "/api/" prefix from path if present.
// Paths that do not begin with "/api/" are returned unchanged.
func StripAPIPrefix(path string) string {
	const prefix = "/api/"
	if strings.HasPrefix(path, prefix) {
		return path[len(prefix):]
	}
	return path
}

package main

import (
	"fmt"
	"strings"
)

// StripAPIPrefix removes the "/api/" prefix from a path if present.
// Paths that do not begin with "/api/" are returned unchanged.
func StripAPIPrefix(path string) string {
	return strings.TrimPrefix(path, "/api/")
}

func main() {
	fmt.Println(StripAPIPrefix("/api/users/42")) // users/42
	fmt.Println(StripAPIPrefix("/health"))        // /health
	fmt.Println(StripAPIPrefix("/api/"))          // ""
}

// Implementation notes:
// We rely on strings.TrimPrefix, which removes the specified prefix from both the
// beginning and the end of the string if it is present, and returns the string
// unchanged otherwise. This means a path like "/api/foo/api/" would have the
// prefix stripped from both sides, which is the behaviour we want for
// normalised route matching. For paths that do not start with "/api/" the
// function is a no-op, so we avoid any extra branching or allocation.

