use reqwest::Client;
use serde::Deserialize;
use std::time::Duration;

#[derive(Debug, Deserialize)]
pub struct Jwks {
    pub keys: Vec<Jwk>,
}

#[derive(Debug, Deserialize)]
pub struct Jwk {
    pub kty: String,
    pub kid: String,
    pub n: String,
    pub e: String,
}

pub fn build_client() -> Client {
    Client::builder()
        // 5 s cap on how long the client waits to establish the TCP/TLS connection
        .timeout(Duration::from_secs(5))
        // Keep idle pooled connections alive for 30 s before recycling
        .pool_idle_timeout(Duration::from_secs(30))
        // Up to 4 idle connections per host in the pool
        .pool_max_idle_per_host(4)
        // Use rustls instead of native-tls for smaller binary / no OpenSSL dep
        .rustls_tls()
        .build()
        .expect("valid client config")
}

pub async fn fetch_jwks(client: &Client, url: &str) -> Result<Jwks, reqwest::Error> {
    let jwks: Jwks = client
        .get(url)
        .send()
        .await?
        .json()
        .await?;
    Ok(jwks)
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let client = build_client();
    let jwks = fetch_jwks(&client, "https://idp.example.com/.well-known/jwks.json").await?;
    println!("Loaded {} JWKs", jwks.keys.len());
    Ok(())
}
```

Notes:
- `timeout(5s)` caps the connection-establishment phase (TCP handshake + TLS), so a slow or unreachable IdP fails fast rather than hanging the request loop.
- `pool_idle_timeout` and `pool_max_idle_per_host` give you predictable connection reuse under burst traffic without letting stale sockets accumulate.
- `rustls_tls()` avoids the OpenSSL system dependency, which simplifies cross-compilation and container images.
- The typed `Jwks`/`Jwk` structs mean a malformed endpoint response surfaces as a `serde` error at the parse boundary rather than a runtime panic later.

