package main

import (
	"encoding/csv"
	"fmt"
	"io"
	"os"
)

func main() {
	f, err := os.Open("data.csv")
	if err != nil {
		fmt.Fprintln(os.Stderr, "open:", err)
		os.Exit(1)
	}
	defer f.Close()

	r := csv.NewReader(f)
	// Allow rows to have any number of fields (keeps mismatched-column rows).
	r.FieldsPerRecord = -1
	// Strict RFC 4180: no LazyQuotes, no TrimLeadingSpace.

	for {
		record, err := r.Read()
		if err != nil {
			if err == io.EOF {
				break
			}
			fmt.Fprintln(os.Stderr, "read:", err)
			break
		}
		fmt.Printf("%v\n", record)
	}
}
```

**Errors ignored (and why):**

1. **`csv.ErrFieldCount` (mismatched column counts):** Suppressed by setting `FieldsPerRecord = -1`. The reader no longer treats a row with a different field count than the first row as an error, so every row is kept regardless of its column count.

2. **Fully-empty lines (bare `\r\n` or `\n` with no field content):** The `encoding/csv` reader skips these automatically (documented behaviour: "The reader skips empty lines"). No explicit error is raised, so nothing to handle.

**Errors NOT ignored (strict RFC 4180):**

- `csv.ErrQuote` – a stray quote outside a quoted field is a genuine parse error under RFC 4180; we let it propagate.
- `csv.ErrBareQuote` – a quote inside an unquoted field; also a strict-mode error we surface.
- `io.EOF` – normal end-of-file, not an error; we break the loop cleanly.
- Any other I/O error (disk, permission, etc.) – we log and exit non-zero.

The code is self-contained: open the file, read every record (variable-width rows included, empty lines skipped), print each row, and stop at EOF or a genuine parse error.

package main

import (
	"encoding/csv"
	"io"
	"os"
)

// ParseCSV reads a CSV file using RFC 4180 quoting rules.
// Rows whose column count differs from the header are preserved.
// Fully-empty lines (a single empty field) are skipped.
func ParseCSV(path string) ([][]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	r := csv.NewReader(f)
	r.FieldsPerRecord = 0 // 0 disables the field-count check, so rows of any width are accepted
	r.LazyQuotes = true   // enables RFC 4180 quote handling

	var rows [][]string
	for {
		record, err := r.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			// We tolerate csv.ErrFieldCount so that mismatched rows survive;
			// any other parse error (bad quote, NUL byte, etc.) is propagated.
			if _, ok := err.(*csv.ParseError); ok {
				continue
			}
			return rows, err
		}
		// Skip fully-empty lines: the reader emits them as a single empty field.
		if len(record) == 1 && record[0] == "" {
			continue
		}
		rows = append(rows, record)
	}
	return rows, nil
}

Errors ignored and why:

1. csv.ErrFieldCount (wrapped in *csv.ParseError): When a data row has a different
   number of fields than the header, the reader returns this error. We skip it
   and keep the partial record because the task explicitly requires preserving
   mismatched rows rather than dropping them.

2. Fully-empty lines: A blank line in the source file is surfaced by the reader
   as a record containing one empty string. We filter those out so they don't
   pollute downstream consumers.

Everything else (unexpected NUL, malformed quoting that LazyQuotes cannot
   rescue, I/O errors) is propagated to the caller.

const http = require('http');

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function retryRequest(options, maxAttempts = 4) {
  const baseDelay = 500; // 500 ms base
  let lastError;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const response = await new Promise((resolve, reject) => {
        const req = http.request(options, (res) => {
          let body = '';
          res.on('data', (chunk) => { body += chunk; });
          res.on('end', () => resolve({ status: res.statusCode, body }));
        });
        req.on('error', reject);
        req.end();
      });

      if (response.status >= 200 && response.status < 300) {
        return response;
      }

      lastError = new Error(`HTTP ${response.status} on attempt ${attempt}`);
    } catch (err) {
      lastError = err;
    }

    // Exponential backoff with full jitter
    if (attempt < maxAttempts) {
      const exponentialDelay = baseDelay * Math.pow(2, attempt - 1);
      const jitter = Math.random() * exponentialDelay;
      const delay = exponentialDelay + jitter;
      console.log(`Attempt ${attempt} failed. Retrying in ${Math.round(delay)} ms ...`);
      await sleep(delay);
    }
  }

  throw new Error(`All ${maxAttempts} attempts failed. Last error: ${lastError.message}`);
}

// --- Example usage ---
async function main() {
  try {
    const result = await retryRequest({
      hostname: 'example.com',
      port: 80,
      path: '/',
      method: 'GET',
    });
    console.log('Success:', result.status, result.body.slice(0, 120));
  } catch (err) {
    console.error('Failed after all retries:', err.message);
  }
}

main();

/*
 * How the backoff works (baseDelay = 500 ms):
 *   attempt 1 fails -> delay = 500  * 2^0 + jitter  =>  500  – 1000 ms
 *   attempt 2 fails -> delay = 500  * 2^1 + jitter  => 1000 – 2000 ms
 *   attempt 3 fails -> delay = 500  * 2^2 + jitter  => 2000 – 4000 ms
 *   attempt 4 fails -> give up (throw)
 *
 * Jitter is uniform in [0, exponentialDelay], so the actual wait is
 * exponentialDelay + U(0, exponentialDelay), i.e. between the base
 * exponential value and twice that value. This spreads out concurrent
 * retrying clients and avoids the thundering-herd problem.
 */

Here's a clean, production-ready retry helper using exponential backoff with full jitter:

```javascript
const { fetch } = require('undici');

async function retryWithBackoff(url, { maxAttempts = 4, baseDelayMs = 500 } = {}) {
  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    try {
      const res = await fetch(url);
      if (res.ok) return res;
      throw new Error(`HTTP ${res.status}`);
    } catch (err) {
      if (attempt === maxAttempts - 1) throw err; // last attempt – surface the error
      // Exponential backoff with jitter
      const delay = baseDelayMs * Math.pow(2, attempt) * (1 + Math.random());
      await new Promise(r => setTimeout(r, delay));
    }
  }
  // Unreachable if all attempts throw, but satisfies linters
  throw new Error('All retry attempts exhausted');
}

module.exports = { retryWithBackoff };
```

How it works:

- **Exponential growth:** the base delay doubles each retry (500 ms → 1 s → 2 s → 4 s for `baseDelayMs = 500`).
- **Jitter:** the `(1 + Math.random())` factor randomises the wait between 1× and 2× the exponential value, so concurrent clients don't all hammer the server at the same instant.
- **Max 4 attempts:** the loop runs exactly four times; on the final failure the original error is re-thrown so the caller can handle it.
- **Non-2xx responses** are treated as failures and retried, while 2xx/3xx responses short-circuit and return the `Response` object.

