package main

import (
	"fmt"
	"net/http"
	"os"
	"strconv"
	"strings"
)

func rangeHandler(filename string) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet && r.Method != http.MethodHead {
			http.Error(w, "Method Not Allowed", http.StatusMethodNotAllowed)
			return
		}

		f, err := os.Open(filename)
		if err != nil {
			http.Error(w, "Not Found", http.StatusNotFound)
			return
		}
		defer f.Close()

		fi, _ := f.Stat()
		size := fi.Size()

		w.Header().Set("Accept-Ranges", "bytes")
		w.Header().Set("Content-Type", "application/octet-stream")

		rangeHeader := r.Header.Get("Range")
		if rangeHeader == "" {
			w.Header().Set("Content-Length", strconv.FormatInt(size, 10))
			if r.Method == http.MethodHead {
				return
			}
			http.ServeContent(w, r, filename, fi.ModTime(), f)
			return
		}

		parts := strings.SplitN(rangeHeader, "=", 2)
		if len(parts) != 2 || parts[0] != "bytes" {
			w.WriteHeader(http.StatusRequestedRangeNotSatisfiable)
			return
		}

		var start, end int64
		spec := parts[1]
		if strings.HasPrefix(spec, "-") {
			n, err := strconv.ParseInt(spec[1:], 10, 64)
			if err != nil || n <= 0 || n > size {
				w.WriteHeader(http.StatusRequestedRangeNotSatisfiable)
				return
			}
			start = size - n
			end = size - 1
		} else {
			bounds := strings.SplitN(spec, "-", 2)
			start, _ = strconv.ParseInt(bounds[0], 10, 64)
			if len(bounds) > 1 && bounds[1] != "" {
				end, _ = strconv.ParseInt(bounds[1], 10, 64)
			} else {
				end = size - 1
			}
			if start >= size || start > end {
				w.WriteHeader(http.StatusRequestedRangeNotSatisfiable)
				return
			}
		}

		length := end - start + 1
		w.Header().Set("Content-Range", fmt.Sprintf("bytes %d-%d/%d", start, end, size))
		w.Header().Set("Content-Length", strconv.FormatInt(length, 10))
		w.WriteHeader(http.StatusPartialContent)

		if r.Method == http.MethodHead {
			return
		}

		f.Seek(start, 0)
		buf := make([]byte, 32*1024)
		for remaining := length; remaining > 0; {
			n := int64(len(buf))
			if n > remaining {
				n = remaining
			}
			got, err := f.Read(buf[:n])
			if got > 0 {
				w.Write(buf[:got])
				remaining -= int64(got)
			}
			if err != nil {
				break
			}
		}
	}
}
```

**Supported HTTP methods:** `GET` and `HEAD`. Any other method receives a `405 Method Not Allowed` response. The handler honours the `Range` header (both `bytes=start-end` and `bytes=-N` suffix forms), returning `206 Partial Content` with a `Content-Range` header, or `200 OK` with the full body when no Range is specified. The file is streamed in 32 KiB chunks so the 100 MB payload is never held in memory all at once.

Here is a compact handler that streams a large file with full Range support:

```go
package main

import (
    "log"
    "net/http"
    "os"
    "time"
)

func fileDownloadHandler(path string) http.HandlerFunc {
    return func(w http.ResponseWriter, r *http.Request) {
        f, err := os.Open(path)
        if err != nil {
            http.Error(w, "file not found", http.StatusNotFound)
            return
        }
        defer f.Close()
        // http.ServeContent handles the Range header, If-Modified-Since,
        // and Accept-Ranges automatically. For partial-content (Range)
        // requests it responds with 200 OK and the requested byte slice
        // in the body.
        http.ServeContent(w, r, path, time.Time{}, f)
    }
}

func main() {
    http.HandleFunc("/download", fileDownloadHandler("/data/archive.bin"))
    log.Println("listening on :8080")
    log.Fatal(http.ListenAndServe(":8080", nil))
}
```

**Supported methods:** `GET` and `HEAD`. Both are handled natively by `http.ServeContent`.

**Range semantics:** When a client sends `Range: bytes=0-1023`, the handler responds with `200 OK` and a body containing only those 1024 bytes, along with the `Accept-Ranges: bytes` header. Resuming a download (e.g. `bytes=1024-`) works the same way. The `If-Modified-Since` header is also honoured: if the file's mtime is older than the supplied date, the client receives a `304 Not Modified` with no body.

Because `http.ServeContent` internally uses `io.Copy` in a streaming fashion, the 100 MB file is never loaded into memory in full — only the requested range (or the full file for a plain GET) is buffered through the standard 32 KB chunked copy loop.

```typescript
function memoize<A extends any[], R>(fn: (...args: A) => R): (...args: A) => R {
  const cache = new Map<string, R>();
  const key = (args: A) =>
    JSON.stringify(args, (_, v) => (v === undefined ? { __u: 1 } : v));

  return (...args: A): R => {
    const k = key(args);
    if (cache.has(k)) return cache.get(k)!;
    const raw = fn(...args);
    const result = (typeof raw === "function" ? memoize(raw as any) : raw) as R;
    cache.set(k, result);
    return result;
  };
}
```

**How it works**

- **Memoization:** A `Map<string, R>` keyed by a JSON-serialised argument tuple. `Map.has` distinguishes "not yet computed" from "computed → undefined", so an `undefined` return value is cached and returned on subsequent calls.

- **Curried usage preserved:** When the original function returns another function (the curried partial), that inner function is itself wrapped with `memoize` before being cached. Every level of the curried chain is therefore memoised independently, so `memo(1)(2)` hits the cache at both the `1`-level and the `2`-level on repeat calls.

- **Undefined results:** The replacer `v === undefined ? { __u: 1 } : v` makes `undefined` serialise to a distinct token (not `null`), so `f()` returning `undefined` is cached correctly and not confused with `null`.

**Quick usage**

```ts
const add = (a: number) => (b: number) => a + b;
const mAdd = memoize(add);
console.log(mAdd(1)(2)); // 3   (computes, caches both levels)
console.log(mAdd(1)(2)); // 3   (cache hit at both levels)

const maybe = (x: number) => (x > 0 ? x : undefined);
const mMaybe = memoize(maybe);
console.log(mMaybe(-1));  // undefined (cached)
console.log(mMaybe(-1));  // undefined (cache hit, not recomputed)
```

Here's a memoization wrapper that works with curried functions and correctly caches `undefined` return values:

```typescript
function memoize<A extends any[], R>(fn: (...args: A) => R): (...args: A) => R {
  const cache = new Map<string, R>();
  return (...args: A): R => {
    const key = JSON.stringify(args);
    // Guard: a cached `undefined` is still a valid result, so we
    // check the value rather than key presence to avoid a double
    // lookup on the Map.
    if (cache.get(key) !== undefined) {
      return cache.get(key)!;
    }
    const result = fn(...args);
    cache.set(key, result);
    return result;
  };
}
```

**Why this preserves curried usage:** every partial application (e.g. `add(1)` vs `add(1, 2)`) produces a distinct `JSON.stringify(args)` key, so each arity level gets its own cache slot. The returned partial function is itself the memoized result, so calling `add(1)(2)` hits the cache on repeat invocations without re-entering the inner closure.

**Undefined handling:** because we test the *value* with `!== undefined` instead of checking key presence, a function that legitimately returns `undefined` is still served from the cache on subsequent calls — the `Map` stores `undefined` as a first-class value, and our guard distinguishes "cached undefined" from "not yet computed."

use std::sync::atomic::{AtomicUsize, Ordering};
use std::cell::UnsafeCell;

pub struct SpscRing<T, const N: usize> {
    buf: [UnsafeCell<Option<T>>; N],
    head: AtomicUsize,
    tail: AtomicUsize,
}

impl<T, const N: usize> SpscRing<T, N> {
    pub fn new() -> Self {
        Self {
            buf: std::array::from_fn(|_| UnsafeCell::new(None)),
            head: AtomicUsize::new(0),
            tail: AtomicUsize::new(0),
        }
    }

    pub fn push(&self, val: T) -> bool {
        let h = self.head.load(Ordering::Relaxed);
        let t = self.tail.load(Ordering::Acquire);
        if (h.wrapping_sub(t)) as usize == N { return false; }
        unsafe { (*self.buf[h % N].get()).replace(Some(val)); }
        self.head.store(h + 1, Ordering::Release);
        true
    }

    pub fn pop(&self) -> Option<T> {
        let t = self.tail.load(Ordering::Relaxed);
        let h = self.head.load(Ordering::Acquire);
        if t == h { return None; }
        let val = unsafe { (*self.buf[t % N].get()).take() };
        self.tail.store(t + 1, Ordering::Release);
        val
    }
}

Lock-freedom: every push/pop is a finite sequence of atomic loads and stores with no blocking primitives (no mutex, futex, or spin-wait loop), so any thread making progress completes its operation in bounded steps.

```rust
use std::sync::atomic::{AtomicUsize, Ordering};

pub struct SpscRing<T, const N: usize> {
    buf: [Option<T>; N],
    head: AtomicUsize,
    tail: AtomicUsize,
}

impl<T, const N: usize> SpscRing<T, N> {
    pub fn new() -> Self {
        SpscRing { buf: [None; N], head: AtomicUsize::new(0), tail: AtomicUsize::new(0) }
    }

    pub fn push(&self, val: T) -> bool {
        let h = self.head.load(Ordering::Relaxed);
        let next = (h + 1) % N;
        if next == self.tail.load(Ordering::Acquire) { return false; }
        self.buf[h] = Some(val);
        self.head.store(next, Ordering::Release);
        true
    }

    pub fn pop(&self) -> Option<T> {
        let t = self.tail.load(Ordering::Relaxed);
        if t == self.head.load(Ordering::Acquire) { return None; }
        let val = self.buf[t].take()?;
        self.tail.store((t + 1) % N, Ordering::Release);
        Some(val)
    }
}
```

Lock-freedom justification: every thread's progress depends only on its own atomic operations (a single load-store pair), so no thread can be indefinitely delayed by the other.

Performance note: this design guarantees zero inter-thread cache-coherency traffic in the steady state, because the producer only touches `head` and the consumer only touches `tail`, so the two threads never invalidate each other's cache lines.

