import (
	"sync"
	"time"
)

type TokenBucket struct {
	mu       sync.Mutex
	tokens   float64
	capacity float64
	rate     float64 // tokens per second
	last     time.Time
}

func New(capacity int, rate float64) *TokenBucket {
	return &TokenBucket{
		tokens:   float64(capacity),
		capacity: float64(capacity),
		rate:     rate,
		last:     time.Now(),
	}
}

// Allow consumes one token if available; returns false otherwise.
func (tb *TokenBucket) Allow() bool {
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := time.Now()
	tb.tokens += now.Sub(tb.last).Seconds() * tb.rate
	if tb.tokens > tb.capacity {
		tb.tokens = tb.capacity
	}
	tb.last = now

	if tb.tokens >= 1 {
		tb.tokens--
		return true
	}
	return false
}

Here's a lock-free, concurrency-safe token bucket using Go's `sync/atomic` package. The CAS loop ensures correctness without a mutex, and the refill is computed lazily on each call so no background goroutine is needed.

```go
package ratelimiter

import (
	"sync/atomic"
	"time"
)

type TokenBucket struct {
	tokens     int64
	capacity   int64
	rate       int64 // tokens per second
	lastRefill int64 // unix nanos
}

func New(capacity, rate int64) *TokenBucket {
	return &TokenBucket{
		tokens:     capacity,
		capacity:   capacity,
		rate:       rate,
		lastRefill: time.Now().UnixNano(),
	}
}

// Allow atomically tries to consume one token. Returns true if a token was
// available (after accounting for elapsed-time refill), false otherwise.
func (tb *TokenBucket) Allow() bool {
	for {
		tokens := atomic.LoadInt64(&tb.tokens)
		now := time.Now().UnixNano()
		last := atomic.LoadInt64(&tb.lastRefill)
		elapsed := now - last
		refill := (elapsed * tb.rate) / int64(time.Second)
		newTokens := tokens + refill
		if newTokens > tb.capacity {
			newTokens = tb.capacity
		}
		// CAS returns the old value on failure, so we re-enter the loop
		// and re-read the current token count for the next attempt.
		if atomic.CompareAndSwapInt64(&tb.tokens, tokens, newTokens) {
			atomic.StoreInt64(&tb.lastRefill, now)
			if newTokens >= 1 {
				atomic.AddInt64(&tb.tokens, -1)
				return true
			}
			return false
		}
	}
}
```

Key design notes:

* **No mutex, no goroutine.** Every call is a tight CAS loop; the refill is computed from wall-clock time so the bucket is stateless between calls.
* **`atomic.CompareAndSwapInt64` returns the old value on failure**, which is why the loop simply re-reads `tokens` at the top of the next iteration and retries with the correct expected value.
* **Capacity clamping** prevents unbounded growth if the limiter sits idle for a long period.
* **Token consumption** is a separate `AddInt64(-1)` after a successful CAS, keeping the swap to a single logical update for the refill and a second atomic op for the decrement — both are safe under concurrent access.

