async function retry<T>(
  fn: () => Promise<T>,
  maxRetries: number,
  delayMs = 1000
): Promise<T> {
  let lastError: unknown;
  for (let i = 0; i <= maxRetries; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      if (i < maxRetries) {
