function deepFreeze<T extends object>(obj: T): T {
  const visited = new WeakSet<object>();
  function freeze(o: object): void {
    if (visited.has(o)) return;
    visited.add(o);
    Object.freeze(o);
    for (const key of Object.getOwnPropertyNames(o)) {
      const v = (o as any)[key];
      if (v && typeof v === "object" && !visited.has(v)) freeze(v);
    }
    for (const key of Object.getOwnPropertySymbols(o)) {
      const v = (o as any)[key];
      if (v && typeof v === "object" && !visited.has(v)) freeze(v);
    }
  }
  freeze(obj);
  return obj;
}

def parse_csv_line(line: str) -> list[str]:
    """Parse a single CSV line, handling quoted fields with embedded commas and doubled quotes."""
    fields: list[str] = []
    current: list[str] = []
    i, n = 0, len(line)
    while i < n:
        if line[i] == '"':
            i += 1
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        current.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    current.append(line[i])
                    i += 1
            fields.append(''.join(current))
            current = []
            if i < n and line[i] == ',':
                i += 1
        elif line[i] == ',':
            fields.append(''.join(current))
            current = []
            i += 1
        else:
            current.append(line[i])
            i += 1
    fields.append(''.join(current))
    return fields
